from transformers import AutoModel
import numpy as np

model = AutoModel.from_pretrained('jinaai/jina-clip-v2', trust_remote_code=True)
text = "Теория графов и алгоритм Дейкстры"
image_path = "data:image/webp;base64,"

text_embedding = model.encode_text([text], truncate_dim=None)
image_embedding = model.encode_image([image_path], truncate_dim=None)

similarity_score = np.dot(text_embedding[0], image_embedding[0].T)

print(f"Similarity score: {similarity_score:.4f}")